
/**
 * One builder-owned generated file identified by its exact bytes.
 *
 * @evidence contracts/common.md#principled-implementation runAutoMovieProductionBuild hashes each generated byte buffer and records its source targets; ownership inspection compares the expected manifest and physical generated tree before publication or reuse.
 * @evidence contracts/common.md#clear-and-simple-design One entry separates portable generated path, exclusive builder ownership, byte identity and source attribution without embedding file content in the manifest.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The builder marker does not itself prove ownership: production checks exact paths, manifest identity and bytes and refuses unowned or unsafe files rather than claiming them.
 * @evidence contracts/common.md#meaningful-documentation States that paths are relative to the generated root, digests identify exact bytes and sourceTargets attribute the producing design or source records.
 * @author Samchon
 */
export interface IAutoMovieGeneratedFile {
  /** Canonical POSIX path relative to the production's generated directory. */
  path: string;

  /** Ownership marker. */
  owner: "builder";

  /** SHA-256 identity of the exact file bytes, formatted as sha256 plus 64 lowercase hexadecimal digits. */
  digest: string;

  /** Design or source targets that produced the file. */
  sourceTargets: string[];
}
